UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Cervical Spine Pain — Non-Traumatic","body":"**This consult covers neck pain WITHOUT acute trauma.** For trauma, use the [Cervical Spine](#/tree/cervical-spine) consult.\n\n[Steps Summary](#/info/csnt-steps)\n\n**First-pass triage — which pattern fits?**\n\n• **Mechanical / Myofascial** — axial neck pain, no radicular or cord features. ~85% of non-traumatic neck pain. [1]\n• **Radicular** — pain or paresthesia in a dermatomal arm distribution, often with myotome weakness or absent reflex.\n• **Myelopathic** — gait disturbance, hand clumsiness, bilateral findings, UMN signs (Hoffman, Babinski, clonus, hyperreflexia).\n• **Red-flag suspicious** — fever, IVDU, cancer history, RA, sudden onset, posterior HA, immunosuppression.\n\n**Always screen for red flags FIRST.** Mechanical neck pain is the most common diagnosis but it is also the most common missed-something diagnosis. [2]","citation":[1,2],"options":[{"label":"Red flags present — screen now","description":"Fever, IVDU, cancer hx, RA, sudden onset, immunocompromise, age >50 with new pain","next":"csnt-redflag-triage","urgency":"critical"},{"label":"Radicular pattern","description":"Dermatomal arm pain or paresthesia, weakness or reflex change","next":"csnt-radic-start"},{"label":"Myelopathy suspected","description":"Gait change, hand clumsiness, bilateral signs, UMN findings","next":"csnt-myelopathy-screen","urgency":"critical"},{"label":"Mechanical / myofascial pain only","description":"Axial neck pain, no radicular or cord features, no red flags","next":"csnt-mech-start"},{"label":"Unsure — distinguish radiculopathy vs myelopathy","description":"Show the side-by-side comparator","next":"csnt-distinguisher"}],"images":[{"src":"images/cervical-spine-nontraumatic/cervical-anatomy.png","alt":"Cervical vertebrae anatomy showing C1-C7, spinal cord, and exiting nerve roots with relationship to disc spaces.","caption":"Cervical vertebrae and exiting nerve roots. (Public Domain, Henry Vandyke Carter / Gray''s Anatomy 1918, via Wikimedia Commons.)"}],"calculatorLinks":[{"id":"cervical-redflag-triage","label":"Red Flag Triage"},{"id":"cervical-myelopathy-screen","label":"Myelopathy Screen"}],"summary":"5-bucket triage — red flags first, then radic vs myelo vs mechanical"}'::jsonb
WHERE id = 'csnt-start' AND tree_id = 'cervical-spine-nontraumatic';

