UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"🚨 Red Flag — Which Concern?","body":"**The \"miss this and lose your license\" differential for non-traumatic neck pain:**\n\n| Red Flag Pattern | Diagnosis to Exclude |\n|---|---|\n| Fever + IVDU / immunosuppression / recent procedure | **Spinal epidural abscess / discitis** |\n| Known cancer + new severe neck pain ± night pain | **Metastatic cord compression (MSCC)** |\n| Sudden onset, posterior HA, neck pain, age <50, post-manipulation | **Vertebral artery dissection** |\n| RA + occipital HA or progressive neuro signs | **Atlantoaxial subluxation** |\n| Fever + neck stiffness + photophobia + headache | **Meningitis** (use [Meningitis](#/tree/meningitis) consult) |\n| Morning stiffness >1 hr, age <40, improves with activity | **Inflammatory spondyloarthropathy** |\n\nWhich pattern fits?","citation":[1,3],"options":[{"label":"Infection (abscess / discitis)","description":"Fever, IVDU, immunosuppression, recent spine procedure, indwelling lines","next":"csnt-redflag-infection","urgency":"critical"},{"label":"Malignancy / MSCC","description":"Known cancer, night pain, weight loss, new-onset severe pain","next":"csnt-redflag-malignancy","urgency":"critical"},{"label":"Vertebral artery dissection","description":"Sudden onset, posterior HA, post-manipulation, posterior circ symptoms","next":"csnt-redflag-vad","urgency":"critical"},{"label":"RA atlantoaxial subluxation","description":"Long-standing RA + occipital HA or new myelopathic signs","next":"csnt-redflag-ra","urgency":"critical"},{"label":"Inflammatory (ank spond, PMR)","description":"Morning stiffness, age, systemic features","next":"csnt-redflag-inflam"}],"summary":"Top misses: abscess, MSCC, dissection, RA AAS, meningitis","safetyLevel":"critical"}'::jsonb
WHERE id = 'csnt-redflag-triage' AND tree_id = 'cervical-spine-nontraumatic';

