UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Vertebral Artery Dissection","body":"VAD is a leading cause of stroke in patients under 45. ~20% of strokes in young adults are from cervicocephalic artery dissection. [6]\n\n**Clinical clues — pain is the herald symptom:**\n• Sudden severe **posterior** neck pain or occipital headache\n• Often after minor trauma, manipulation (chiropractic), neck rotation, sustained extension (hair-washing, ceiling painting)\n• \"Worst headache of life\" in the back of the head\n• Posterior circulation symptoms: vertigo, diplopia, dysarthria, ataxia, hemianopsia, dysphagia\n• Horner syndrome (carotid dissection more typical but VAD can cause it)\n\n**Use the [Cervical Artery Dissection](#/tree/cervical-artery-dissection) consult for the full pathway.**\n\n**Quick ED actions:**\n• **CTA neck** (faster, more available) or MRA neck — both 95-100% sensitive [6]\n• Neurology consult\n• Antithrombotic therapy: **antiplatelet (aspirin) vs anticoagulation** — recent CADISS, TREAT-CAD trials show similar outcomes; aspirin is the typical first-line in most ED settings\n• Avoid neck manipulation, vigorous physical therapy\n• Admit for stroke workup, telemetry, repeat imaging\n\n**Do NOT:** intubate or move the neck aggressively without considering ongoing dissection / clot propagation.","citation":[6],"next":"csnt-disposition","summary":"Posterior HA + neck pain + young = CTA neck — see CAD consult","safetyLevel":"critical"}'::jsonb
WHERE id = 'csnt-redflag-vad' AND tree_id = 'cervical-spine-nontraumatic';

